/**
 * @file muscle_actuator.h
 * @brief Compiled zero-allocation Port-Hamiltonian model generated by RT-MPBC.
 * Standard: MISRA-C:2012 / C99 bare-metal compatible.
 */

#ifndef RTMPBC_COMPILED_MUSCLE_ACTUATOR_H
#define RTMPBC_COMPILED_MUSCLE_ACTUATOR_H

#include "rtmpbc.h"

#define MUSCLE_ACTUATOR_N_STATES 2
#define MUSCLE_ACTUATOR_N_INPUTS 1
#define MUSCLE_ACTUATOR_INPUTS_DIM 1
#define MUSCLE_ACTUATOR_DT 0.0005000000

/* State variable indexing */
#define MUSCLE_ACTUATOR_STATE_C_EPIDERMAL_MEMBRANE 0
#define MUSCLE_ACTUATOR_STATE_I_FOREARM_INERTIA 1

/* Input port indexing */
#define MUSCLE_ACTUATOR_INPUT_V_STIMULATION 0

typedef struct {
    rtmpbc_real_t x[MUSCLE_ACTUATOR_N_STATES];
    rtmpbc_real_t u[MUSCLE_ACTUATOR_INPUTS_DIM];
    rtmpbc_real_t y[MUSCLE_ACTUATOR_INPUTS_DIM];
    rtmpbc_real_t total_energy;
} muscle_actuator_sim_t;

void muscle_actuator_init(muscle_actuator_sim_t* sim);
void muscle_actuator_step(muscle_actuator_sim_t* sim);
rtmpbc_real_t muscle_actuator_energy(const muscle_actuator_sim_t* sim);

#endif /* RTMPBC_COMPILED_MUSCLE_ACTUATOR_H */
